class Solution {
public:
    int maxIncreasingSubarrays(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        int prevRunLen = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && nums[j] < nums[j + 1]) {
                j++;
            }
            int runLen = j - i + 1;
            ans = max(ans, runLen / 2);
            if (prevRunLen > 0) {
                ans = max(ans, min(prevRunLen, runLen));
            }
            prevRunLen = runLen;
            i = j + 1;
        }
        return ans;
    }
};
